def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    my_last, opp_last = history[-1]

    # Track opponent behavior over the whole match.
    opp_def = 0
    my_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1

    # Near-perfect cooperator: exploit gently and safely at the very end.
    if opp_def == 0:
        if n >= 96:
            return 'D'
        return 'C'

    # Pure defector: no point cooperating.
    if opp_def == n:
        return 'D'

    # Count recent window statistics.
    start = n - 8
    if start < 0:
        start = 0
    r_opp_def = 0
    r_my_def = 0
    last_opp_def_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            last_opp_def_run += 1
        else:
            break
    for i in range(start, n):
        if history[i][1] == 'D':
            r_opp_def += 1
        if history[i][0] == 'D':
            r_my_def += 1
    r_len = n - start

    # Endgame exploitation of conditionally cooperative opponents.
    if n >= 97:
        return 'D'
    if n >= 94 and opp_def <= 3:
        return 'D'

    # Very cooperative opponent: keep cooperating, small late probing.
    if opp_def <= 1:
        if n >= 88 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # Opponent is currently in a defection streak: retaliate, but avoid
    # endless DD loops by occasionally offering a fresh cooperation.
    if opp_last == 'D':
        if last_opp_def_run >= 3:
            # Long vendetta: try one cooperative olive branch.
            if rng.random() < 0.12 and n < 90:
                return 'C'
            return 'D'
        if last_opp_def_run == 2:
            return 'D'
        # Single defection: forgive quickly if opponent is mostly cooperative.
        if opp_def * 4 <= n:
            return 'C'
        # Moderate defector: retaliate with some forgiveness.
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If we were defecting a lot recently and opponent still cooperates,
    # return to cooperation to avoid losing mutual gains.
    if r_my_def >= 4 and r_opp_def <= 1:
        return 'C'

    # Detect highly cooperative opponent, keep cooperating.
    if opp_def * 5 <= n:
        # Rarely probe with D to test, but only after enough history.
        if n >= 60 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Opponent moderately defective recently: play conditional cooperation.
    if r_len >= 6 and r_opp_def >= 3:
        if r_opp_def * 2 >= r_len:
            return 'D'
        return 'C'

    # Detect whether opponent punishes our defections: if our defections
    # tend to be followed by opponent defections, be careful.
    if n >= 6:
        punish = 0
        count = 0
        for i in range(n - 1):
            if history[i][0] == 'D':
                count += 1
                if history[i + 1][1] == 'D':
                    punish += 1
        if count >= 2 and punish * 2 >= count:
            return 'C'
        if count >= 2 and punish * 3 <= count:
            # Opponent tolerates defection -> exploit moderately.
            if opp_def * 3 <= n and rng.random() < 0.4:
                return 'D'

    return 'C'
